import { fireEvent, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import type { LlmCallRecord } from "../../../types";
import { llmCallToConversationEvent } from "../../../utils/llm-calls";
import { LlmCallEvent } from "./LlmCallEvent";

function makeRecord(overrides: Partial<LlmCallRecord>): LlmCallRecord {
  return {
    id: "r1",
    timestamp: 100,
    purpose: null,
    request_model: "gpt-4o",
    response_model: null,
    input_tokens: null,
    output_tokens: null,
    latency_ms: 250,
    time_to_first_token_ms: null,
    tool_names: [],
    gated_tool_names: [],
    response_tool_names: [],
    prompt_messages: null,
    response_messages: null,
    is_error: false,
    error_message: null,
    ...overrides,
  };
}

describe("LlmCallEvent", () => {
  it("shows the model and duration in the log row", () => {
    renderWithProviders(
      <LlmCallEvent event={llmCallToConversationEvent(makeRecord({}))} isSelected={false} />,
    );
    const row = screen.getByTestId("llm-call-event");
    expect(row).toHaveTextContent("LLM call");
    expect(row).toHaveTextContent("gpt-4o");
    expect(row).toHaveTextContent("250 ms");
  });

  it("marks failed calls with an error dot", () => {
    renderWithProviders(
      <LlmCallEvent
        event={llmCallToConversationEvent(makeRecord({ is_error: true }))}
        isSelected={false}
      />,
    );
    expect(screen.getByTestId("error-dot")).toBeInTheDocument();
  });

  it("toggles expansion without selecting the row", () => {
    const onClick = vi.fn();
    const onToggleExpand = vi.fn();
    const event = llmCallToConversationEvent(makeRecord({}));
    const { rerender } = renderWithProviders(
      <LlmCallEvent
        event={event}
        isSelected={false}
        onClick={onClick}
        expanded={false}
        onToggleExpand={onToggleExpand}
      />,
    );

    const toggle = screen.getByTestId("llm-call-toggle");
    expect(toggle).toHaveAttribute("aria-label", "Expand LLM call events");

    fireEvent.click(toggle);
    expect(onToggleExpand).toHaveBeenCalledTimes(1);
    expect(onClick).not.toHaveBeenCalled();

    rerender(
      <LlmCallEvent
        event={event}
        isSelected={false}
        onClick={onClick}
        expanded={true}
        onToggleExpand={onToggleExpand}
      />,
    );
    expect(screen.getByTestId("llm-call-toggle")).toHaveAttribute(
      "aria-label",
      "Collapse LLM call events",
    );
  });

  it("renders the purpose suffix for side-channel calls", () => {
    renderWithProviders(
      <LlmCallEvent
        event={llmCallToConversationEvent(makeRecord({ purpose: "fact discovery" }))}
        isSelected={false}
      />,
    );
    expect(screen.getByTestId("llm-call-event")).toHaveTextContent("· fact discovery");
  });
});
